  // ------------------------------------------------- the middle-school editions
  //
  // An edition is the same place and the same cast teaching a different course,
  // so it gets its own entry here rather than inheriting one. Inheriting would
  // measure a grade-6 campaign against a syllabus it is not trying to cover and
  // report thirty gaps, which is a measurement that says nothing — the failure
  // the readability note in CLAUDE.md is about.
  //
  // Twelve to sixteen concepts, not thirty: a ten-day campaign has thirty stops
  // in it, and a syllabus longer than that is a list of things the game was
  // always going to miss.
