  // AP Statistics, all nine units. Sixteen equations — the four test statistics
  // at the end are units 6 to 9, which the base game's syllabus never computes.
  the_trial_hs: [
    { e: 'x̄ = Σx / n', c: 'the sample mean',
      v: [['x̄', 'the sample mean'], ['Σx', 'the sum of the observations'], ['n', 'how many there are']],
      s: 'Add the values and divide by how many, which is why one extreme value can drag it.',
      k: ['mean of', 'average of the', 'sum of the'] },
    { e: 's = √(Σ(x − x̄)² / (n − 1))', c: 'the sample standard deviation',
      needs: ['x̄ = Σx / n'],
      v: [['s', 'sample standard deviation'], ['x − x̄', 'each distance from the mean'],
          ['n − 1', 'the degrees of freedom, one fewer than the count']],
      s: 'Square the distances so they cannot cancel, average them over n − 1, and take the root to get back to the original units.',
      k: ['standard deviation', 'spread of', 'typical distance'] },
    { e: 'z = (x − μ) / σ', c: 'standardising a value',
      needs: ['s = √(Σ(x − x̄)² / (n − 1))'],
      v: [['z', 'the standardised value'], ['x', 'the observation'], ['μ', 'the mean'],
          ['σ', 'the standard deviation']],
      s: 'A z-score is how many standard deviations from the mean a value sits, which makes two different scales comparable.',
      k: ['z-score', 'standardis', 'standardiz', 'how many standard deviations'] },
    { e: 'ŷ = a + bx', c: 'the least-squares line',
      needs: ['z = (x − μ) / σ'],
      v: [['ŷ', 'the predicted value'], ['a', 'the intercept'], ['b', 'the slope, in y-units per x-unit'],
          ['x', 'the explanatory value you are predicting from']],
      s: 'The slope is what one more unit of x is worth in y, and the intercept is where the line crosses at x = 0.',
      k: ['regression line', 'predicted', 'slope', 'intercept'] },
    { e: 'b = r · (s_y / s_x)', c: 'the slope from the correlation',
      needs: ['ŷ = a + bx'],
      v: [['b', 'the slope of the least-squares line'], ['r', 'the correlation coefficient'],
          ['s_y', 'standard deviation of the response'], ['s_x', 'standard deviation of the explanatory variable']],
      s: 'The slope is the correlation scaled by the two spreads, which is why r alone says nothing about units.',
      k: ['correlation', 'slope from r', 'coefficient r'] },
    { e: 'residual = y − ŷ', c: 'a residual',
      needs: ['ŷ = a + bx'],
      v: [['y', 'what was observed'], ['ŷ', 'what the line predicted']],
      s: 'A residual is what the line missed by, and a pattern in the residuals means the line is the wrong shape.',
      k: ['residual', 'observed minus predicted', 'left over'] },
    { e: 'P(A or B) = P(A) + P(B) − P(A and B)', c: 'the addition rule',
      v: [['P(A or B)', 'the chance at least one happens'],
          ['P(A and B)', 'the chance both do, subtracted so it is not counted twice']],
      s: 'Adding two chances counts the overlap twice, so it has to come back off once.',
      k: ['probability that either', 'addition rule', 'at least one', 'mutually exclusive'] },
    { e: 'P(A|B) = P(A and B) / P(B)', c: 'conditional probability',
      needs: ['P(A or B) = P(A) + P(B) − P(A and B)'],
      v: [['P(A|B)', 'the chance of A given that B happened'],
          ['P(B)', 'the chance of the condition itself']],
      s: 'Conditioning narrows the population to the cases where B is true, and asks about A inside that.',
      k: ['conditional probability', 'given that', 'among those who', 'independent'] },
    { e: 'E(X) = Σx·P(x)', c: 'the expected value of a random variable',
      needs: ['P(A|B) = P(A and B) / P(B)'],
      v: [['E(X)', 'the long-run average value'], ['x', 'each possible value'],
          ['P(x)', 'its probability']],
      s: 'Weight every outcome by how often it happens, and the total is what you would average over the long run.',
      k: ['expected value', 'long run average', 'expected number of'] },
    { e: 'P(X = k) = C(n,k)·pᵏ(1−p)ⁿ⁻ᵏ', c: 'the binomial probability',
      needs: ['E(X) = Σx·P(x)'],
      v: [['n', 'the fixed number of trials'], ['k', 'the number of successes asked about'],
          ['p', 'the chance of success on one trial'], ['C(n,k)', 'the number of ways k can fall among n']],
      s: 'Any one arrangement has probability pᵏ(1−p)ⁿ⁻ᵏ, and there are C(n,k) arrangements that count.',
      k: ['binomial', 'exactly', 'number of successes', 'out of the'] },
    { e: 'σ_p̂ = √(p(1−p)/n)', c: 'the standard error of a proportion',
      needs: ['P(X = k) = C(n,k)·pᵏ(1−p)ⁿ⁻ᵏ'],
      v: [['σ_p̂', 'the spread of the sample proportion from sample to sample'],
          ['p', 'the true proportion'], ['n', 'the sample size']],
      s: 'The spread falls as the root of the sample size, so quartering it takes four times the data.',
      k: ['of a proportion', 'p(1−p)', 'proportion would wobble'] },
    { e: 'σ_x̄ = σ / √n', c: 'the standard error of a mean',
      needs: ['z = (x − μ) / σ'],
      v: [['σ_x̄', 'the spread of the sample mean'], ['σ', 'the spread of one observation'],
          ['n', 'the sample size']],
      s: 'Averaging cancels noise at the rate of the root of n, which is the whole reason a trial enrols more than one person.',
      k: ['standard error of the mean', 'central limit', 'averaging cancels'] },
    { e: 'CI = statistic ± z*·SE', c: 'a confidence interval',
      needs: ['σ_x̄ = σ / √n', 'σ_p̂ = √(p(1−p)/n)'],
      v: [['statistic', 'the estimate from the sample'], ['z*', 'the critical value for the level, 1.96 at 95%'],
          ['SE', 'the standard error of that statistic']],
      s: 'The interval is the estimate plus and minus a margin, and the level decides how many standard errors wide that margin is.',
      k: ['confidence interval', 'margin of error', 'plus or minus', '95%'] },
    { e: 'z = (p̂ − p₀) / √(p₀(1−p₀)/n)', c: 'the test statistic for one proportion',
      needs: ['CI = statistic ± z*·SE'],
      v: [['p̂', 'the observed proportion'], ['p₀', 'the proportion the null hypothesis names'],
          ['n', 'the sample size']],
      s: 'Divide how far the observation sits from the claim by how far it would scatter if the claim were true.',
      k: ['test statistic', 'p-value', 'null hypothesis', 'z of'] },
    { e: 't = (x̄₁ − x̄₂) / √(s₁²/n₁ + s₂²/n₂)', c: 'the two-sample t statistic',
      needs: ['CI = statistic ± z*·SE'],
      v: [['x̄₁, x̄₂', 'the two sample means'], ['s₁, s₂', 'their standard deviations'],
          ['n₁, n₂', 'their sample sizes']],
      s: 'The difference between two means, measured in units of how much that difference would wobble by itself.',
      k: ['t statistic', 'two-sample', 'difference in means', 'degrees of freedom'] },
    { e: 'χ² = Σ(O − E)² / E', c: 'the chi-square statistic on a table of counts',
      needs: ['z = (p̂ − p₀) / √(p₀(1−p₀)/n)'],
      v: [['O', 'the count observed in a cell'], ['E', 'the count expected there if the null were true'],
          ['Σ', 'summed over every cell of the table']],
      s: 'Each cell contributes its squared shortfall relative to what was expected there, so big cells do not dominate by being big.',
      k: ['chi-square', 'expected count', 'observed count', 'table of'] },
  ],
  // AP Environmental Science on Vellan Island. Sixteen equations, and every one
